SELECT ?s ?lbl ?cls ?tsid WHERE {
  ?s brick:hasLabel ?lbl .
  ?s a ?cls .
  FILTER(?lbl = "Perimeter_mid_ZN_3" || ?lbl = "DataCenter_top_ZN_6")
  OPTIONAL { ?s ref:hasTimeseriesId ?tsid }
}

SELECT ?s ?lbl ?cls WHERE {
  ?s brick:hasLabel ?lbl .
  FILTER(CONTAINS(STR(?lbl), "ZN_3"))
  OPTIONAL { ?s a ?cls }
}

SELECT ?s ?lbl ?cls WHERE {
  ?s brick:hasLabel ?lbl .
  FILTER(CONTAINS(STR(?lbl), "ZN_6") || CONTAINS(STR(?lbl), "DataCenter"))
  OPTIONAL { ?s a ?cls }
}

SELECT ?s ?lbl ?cls WHERE {
  ?s rdfs:label ?lbl .
  FILTER(CONTAINS(STR(?lbl), "ZN_3") || CONTAINS(STR(?lbl), "ZN_6") || CONTAINS(STR(?lbl), "DataCenter") || CONTAINS(STR(?lbl), "Perimeter"))
  OPTIONAL { ?s a ?cls }
}

SELECT ?zone ?sensor ?pts ?tsid WHERE {
  ?sensor brick:hasProperty ?pts .
  ?sensor a brick:Occupancy_Sensor .
  ?sensor brick:hasSubEntity ?zone .
  FILTER(?zone IN (
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02>,
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z09>))
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsid }
}

SELECT ?sensor ?rel ?other WHERE {
  ?s a brick:Occupancy_Sensor .
  ?s ?rel ?o .
  FILTER(?rel != rdf:type)
} LIMIT 30

